/**
 * Recommendation Engine (brief §17/§24) — the stable, structured result
 * contract. Composes the existing DecisionOutput (scores, ranking,
 * narrative fields — unchanged) with the new Constraint/Evidence/
 * Confidence/Scenario engines into one typed shape, rather than
 * inventing a second narrative layer. Every field here is either
 * copied from an already-computed value or derived by a pure function
 * of those values — nothing is generated by an LLM.
 */
import { ENGINE_VERSION, SCORING_ENGINE_VERSION } from "./engine-version";
import { evaluateConstraints, rollupEligibility, type Eligibility } from "./constraints";
import { buildEngineEvidence, computeEvidenceDiagnostics, type EvidenceDiagnostics } from "./evidence";
import { evaluateConfidence, type ConfidenceResult } from "./confidence";
import { findPivotalDimensions, robustnessAcrossStressScenarios, type PivotalDimension } from "./scenario";
import type { DecisionOutput } from "../types";
import type { WizardState } from "../types";

export interface RankingEntry {
  id: string;
  name: string;
  score: number;
  eligibility: Eligibility;
}

export interface EngineResult {
  engineVersion: string;
  scoringModelVersion: string;
  recommendedOption: { id: string; name: string };
  score: number;
  ranking: RankingEntry[];
  criteriaBreakdown: DecisionOutput["dimensions"];
  constraints: ReturnType<typeof evaluateConstraints>;
  evidenceDiagnostics: EvidenceDiagnostics;
  assumptions: string[];
  risks: string[];
  scenarios: {
    pivotalDimensions: PivotalDimension[];
    robust: boolean;
    winnerChangedUnder: string[];
  };
  confidence: ConfidenceResult;
  tradeoffs: string[];
  conditionsToReconsider: string[];
  nextActions: string[];
}

function buildTradeoffs(output: DecisionOutput): string[] {
  if (!output.alternativeRecommendation) return [];
  const winnerConcerns = output.concerns.slice(0, 2).map((c) => c.text);
  const runnerUpStrength = output.alternativeRecommendation.dimensions
    .filter((d) => d.positiveEvidence.length > 0)
    .sort((a, b) => b.score - a.score)[0];

  const tradeoffs = [...winnerConcerns];
  if (runnerUpStrength) {
    tradeoffs.push(
      `${output.alternativeRecommendation.platform.productName} scores higher on ${runnerUpStrength.label} (${runnerUpStrength.score}%), the main reason it remains the alternative.`,
    );
  }
  return tradeoffs;
}

function buildConditionsToReconsider(
  pivotalDimensions: PivotalDimension[],
  constraintEvaluations: ReturnType<typeof evaluateConstraints>,
): string[] {
  const conditions: string[] = [];

  const unknownConstraints = constraintEvaluations.filter((c) => c.status === "UNKNOWN");
  for (const c of unknownConstraints) {
    conditions.push(`If ${c.label.toLowerCase()} becomes a hard requirement, re-run this assessment with it specified.`);
  }

  const flippable = pivotalDimensions
    .filter((p): p is PivotalDimension & { weightToTie: number } => p.weightToTie !== null)
    .sort((a, b) => Math.abs(a.weightToTie - a.currentWeight) - Math.abs(b.weightToTie - b.currentWeight))
    .slice(0, 2);
  for (const p of flippable) {
    const direction = p.weightToTie > p.currentWeight ? "increases" : "decreases";
    conditions.push(
      `If ${p.label}'s priority ${direction} enough to move its weight from ${Math.round(p.currentWeight * 100)}% to about ${Math.round(p.weightToTie * 100)}%, the recommendation would change.`,
    );
  }

  return conditions;
}

export function buildEngineResult(state: WizardState, output: DecisionOutput): EngineResult {
  const ranked = [output.recommendation, ...output.alternatives];
  const winner = output.recommendation;

  const constraintEvaluations = evaluateConstraints(state.constraints, winner.platform);
  const evidence = buildEngineEvidence(state, winner);
  const evidenceDiagnostics = computeEvidenceDiagnostics(evidence, winner.dimensions, winner.platform);
  const confidence = evaluateConfidence(state, winner, evidenceDiagnostics);
  const pivotalDimensions = findPivotalDimensions(ranked);
  const { robust, winnerChangedUnder } = robustnessAcrossStressScenarios(ranked);

  const ranking: RankingEntry[] = ranked.map((r) => ({
    id: r.platform.id,
    name: `${r.platform.vendor} ${r.platform.productName}`,
    score: r.overallScore,
    eligibility: rollupEligibility(evaluateConstraints(state.constraints, r.platform)),
  }));

  return {
    engineVersion: ENGINE_VERSION,
    scoringModelVersion: SCORING_ENGINE_VERSION,
    recommendedOption: { id: winner.platform.id, name: `${winner.platform.vendor} ${winner.platform.productName}` },
    score: output.donnaScore,
    ranking,
    criteriaBreakdown: output.dimensions,
    constraints: constraintEvaluations,
    evidenceDiagnostics,
    assumptions: output.assumptions.map((a) => a.text),
    risks: output.risks.map((r) => r.text),
    scenarios: {
      pivotalDimensions,
      robust,
      winnerChangedUnder: winnerChangedUnder as string[],
    },
    confidence,
    tradeoffs: buildTradeoffs(output),
    conditionsToReconsider: buildConditionsToReconsider(pivotalDimensions, constraintEvaluations),
    nextActions: output.nextSteps.map((s) => s.text),
  };
}
